DELETE FROM organization WHERE id IN (SELECT m."organizationId" FROM membership m JOIN "user" u ON u.id = m."userId" WHERE u.email = 'demo@quercy.app') OR id = 'quercy_demo_org';
DELETE FROM "user" WHERE email LIKE '%@quercy.app';

