-- Votre compte : propriétaire de l'espace, qui devient l'espace ouvert à la prochaine page.
SELECT 'demo_owner_' || u.id, r."organizationId", u.id, r.id, now(), now()
FROM "user" u JOIN role r ON r."organizationId" = 'quercy_demo_org' AND r."systemKey" = 'owner'
WHERE u.email = 'safoloumami@gmail.com';
UPDATE session SET "activeOrganizationId" = 'quercy_demo_org'
WHERE "userId" IN (SELECT id FROM "user" WHERE email = 'safoloumami@gmail.com');
-- Une partie du travail vous est attribuée (widgets « Mes tâches », « Mes activités »…).
UPDATE task SET "ownerId" = (SELECT id FROM "user" WHERE email = 'safoloumami@gmail.com')
WHERE id IN (SELECT id FROM task WHERE "organizationId" = 'quercy_demo_org' ORDER BY id LIMIT 30);
UPDATE activity SET "ownerId" = (SELECT id FROM "user" WHERE email = 'safoloumami@gmail.com')
WHERE id IN (SELECT id FROM activity WHERE "organizationId" = 'quercy_demo_org' ORDER BY id LIMIT 60);
UPDATE ticket SET "ownerId" = (SELECT id FROM "user" WHERE email = 'safoloumami@gmail.com')
WHERE id IN (SELECT id FROM ticket WHERE "organizationId" = 'quercy_demo_org' ORDER BY id LIMIT 10);
UPDATE event SET "ownerId" = (SELECT id FROM "user" WHERE email = 'safoloumami@gmail.com')
WHERE id IN (SELECT id FROM event WHERE "organizationId" = 'quercy_demo_org' ORDER BY id LIMIT 15);
UPDATE deal SET "ownerId" = (SELECT id FROM "user" WHERE email = 'safoloumami@gmail.com')
WHERE id IN (SELECT id FROM deal WHERE "organizationId" = 'quercy_demo_org' ORDER BY id LIMIT 12);
SELECT 'demo_welcome_' || u.id, 'quercy_demo_org', u.id, 'welcome',
